function deckReviewCount(deck){return deck.cards.reduce((total,card)=>total+(card.seen||0),0)}
function overviewContinueDeck(deck,index){
  const total=deck.cards.length,learned=deck.cards.filter(card=>card.interval>0).length,reviewed=deck.cards.filter(card=>card.seen>0).length,due=dueCards(deck).length,progress=total?Math.round(learned/total*100):0,[bg,fg]=deckColor(index);
  return `<article class="overview-continue-deck"><span class="overview-deck-icon" style="background:${bg};color:${fg}">${deckIcon(deck)}</span><div class="overview-deck-main"><div class="overview-deck-title"><strong>${esc(deck.name)}</strong><span>${total} ${total===1?'card':'cards'}</span></div><div class="overview-deck-progress"><span><i style="width:${progress}%"></i></span><small>${progress}% learned</small></div><div class="overview-deck-meta">${reviewed?`${reviewed} cards practiced`:'Ready to start'} · ${due} due</div></div><button class="secondary-button" data-action="study-deck" data-id="${deck.id}">${reviewed?'Continue':'Start'}<i data-lucide="arrow-right"></i></button></article>`
}
function overviewSessionDate(day){const parts=String(day||'').split('-').map(Number);if(parts.length!==3||parts.some(Number.isNaN))return 'Study session';const date=new Date(parts[0],parts[1],parts[2]);return new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(date)}
function styledDeckCard(d,i){const all=d.cards.length,learned=d.cards.filter(c=>c.interval>0).length,practice=d.cards.filter(c=>c.seen>0&&c.interval===0).length,notStudied=d.cards.filter(c=>!c.seen).length,progress=all?Math.round(learned/all*100):0,[bg,fg]=deckColor(i);return `<article class="app-library-card" style="--card-delay:${Math.min(i,8)*45}ms" data-open-deck="${d.id}"><div class="app-library-top"><span class="app-deck-emoji" style="background:${bg};color:${fg}">${deckIcon(d)}</span><div class="app-library-menu"><button class="more-button" data-menu="${d.id}" aria-label="${esc(d.name)} options">···</button><div class="menu-pop" id="menu-${d.id}" hidden><button data-action="edit-deck" data-id="${d.id}">Edit deck</button><button data-action="delete-deck" data-id="${d.id}">Delete deck</button></div></div></div><div class="app-library-subject">${esc(d.subject||'General')}</div><h3>${esc(d.name)}</h3><p class="app-library-description">${esc(d.description||`Review ${esc(d.subject||'your subject')} a little at a time.`)}</p><div class="app-library-summary"><span>${all} flashcards</span><strong>${progress}% learned</strong></div><div class="app-library-track"><span style="width:${progress}%"></span></div><div class="app-library-counts"><div><strong>${learned}</strong><span>Learned</span></div><div><strong>${practice}</strong><span>Practice</span></div><div><strong>${notStudied}</strong><span>Not studied</span></div></div><div class="app-library-actions"><button class="secondary-button" data-action="open-deck" data-id="${d.id}">Open Deck</button><button class="primary-button" data-action="study-deck" data-id="${d.id}"><i data-lucide="play"></i>Study Deck</button></div></article>`}
function sliderControls(label,trackId){return `<div class="recall-slider-controls" hidden><button class="slider-arrow" type="button" data-slider-prev aria-label="Previous ${label}" aria-controls="${trackId}"><i data-lucide="arrow-left"></i></button><button class="slider-arrow" type="button" data-slider-next aria-label="Next ${label}" aria-controls="${trackId}"><i data-lucide="arrow-right"></i></button></div>`}
let sliderResizeBound=false;
function updateHorizontalSlider(slider){const viewport=slider?.querySelector('.recall-slider-viewport'),track=slider?.querySelector('.recall-slider-track'),controls=slider?.querySelector('.recall-slider-controls');if(!viewport||!track||!controls)return;const prev=controls.querySelector('[data-slider-prev]'),next=controls.querySelector('[data-slider-next]'),maxScroll=Math.max(0,viewport.scrollWidth-viewport.clientWidth),hasSlides=!!track.querySelector('.app-library-card,.app-flashcard-item'),hasOverflow=hasSlides&&maxScroll>2;controls.hidden=!hasOverflow;if(prev)prev.disabled=!hasOverflow||viewport.scrollLeft<=2;if(next)next.disabled=!hasOverflow||viewport.scrollLeft>=maxScroll-2}
function initHorizontalSliders(root=document){root.querySelectorAll('[data-horizontal-slider]').forEach(slider=>{const viewport=slider.querySelector('.recall-slider-viewport'),track=slider.querySelector('.recall-slider-track');if(!viewport||!track)return;bindOnce(slider,'click',event=>{const button=event.target.closest('[data-slider-prev],[data-slider-next]');if(!button||button.disabled)return;const card=track.querySelector('.app-library-card,.app-flashcard-item'),gap=parseFloat(getComputedStyle(track).columnGap)||16,step=(card?.getBoundingClientRect().width||viewport.clientWidth)+gap,maxScroll=Math.max(0,viewport.scrollWidth-viewport.clientWidth),target=button.hasAttribute('data-slider-next')?Math.min(maxScroll,viewport.scrollLeft+step):Math.max(0,viewport.scrollLeft-step);viewport.scrollTo({left:target,behavior:'smooth'})});bindOnce(viewport,'scroll',()=>updateHorizontalSlider(slider));updateHorizontalSlider(slider)});if(!sliderResizeBound){window.addEventListener('resize',()=>document.querySelectorAll('[data-horizontal-slider]').forEach(updateHorizontalSlider));sliderResizeBound=true}}
function library(){const all=allCards(),learned=all.filter(c=>c.interval>0).length,practice=all.filter(c=>c.seen>0&&c.interval===0).length,subjects=[...new Set(state.decks.map(d=>d.subject||'General'))].sort();return `<div class="app-library"><section class="app-overview-head"><div><h1>My Decks</h1><p>Organise your subjects and keep all your learning materials in one place.</p></div><button class="primary-button" data-action="new-deck"><span class="button-icon"><i data-lucide="plus"></i></span>Create New Deck</button></section><section class="grid app-overview-stats"><article class="stat-card app-stat"><div class="stat-top">Total Decks <span class="app-stat-icon"><i data-lucide="layers-2"></i></span></div><div class="app-stat-number">${state.decks.length}</div><div class="stat-note">Your personal collections</div></article><article class="stat-card app-stat"><div class="stat-top">Total Flashcards <span class="app-stat-icon"><i data-lucide="copy"></i></span></div><div class="app-stat-number">${all.length}</div><div class="stat-note">Across all your decks</div></article><article class="stat-card app-stat learned"><div class="stat-top">Cards Learned <span class="app-stat-icon"><i data-lucide="circle-check"></i></span></div><div class="app-stat-number">${learned}</div><div class="stat-note">Successfully reviewed</div></article><article class="stat-card app-stat practice"><div class="stat-top">Further Practice <span class="app-stat-icon"><i data-lucide="rotate-cw"></i></span></div><div class="app-stat-number">${practice+all.filter(c=>!c.seen).length}</div><div class="stat-note">${stats().due} cards ready to review</div></article></section><div class="app-library-tabs" role="tablist"><button class="app-library-tab active" data-library-filter="all">All decks <span>${state.decks.length}</span></button><button class="app-library-tab" data-library-filter="practice">Needs practice</button><button class="app-library-tab" data-library-filter="recent">Recently studied</button></div><div class="app-library-toolbar"><label class="app-library-search"><i data-lucide="search"></i><input id="deckSearch" type="search" placeholder="Search by deck name..." aria-label="Search decks"></label><select id="deckSubject" aria-label="Filter by subject"><option value="all">All subjects</option>${subjects.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="deckSort" aria-label="Sort decks"><option value="added">Sort: Recently added</option><option value="recent">Sort: Recently studied</option><option value="name">Sort: Name</option><option value="cards">Sort: Most cards</option><option value="due">Sort: Most due</option></select><div class="app-layout-toggle"><button class="active" data-layout="grid" aria-label="Grid view"><i data-lucide="grid-2x2"></i></button><button data-layout="list" aria-label="List view"><i data-lucide="list"></i></button></div></div><div class="app-library-title"><h2>Your decks</h2><span id="appDeckCount">${state.decks.length} decks</span></div><div class="recall-horizontal-slider" data-horizontal-slider="decks">${sliderControls('decks','libraryGrid')}<div class="recall-slider-viewport"><div id="libraryGrid" class="grid app-library-grid recall-slider-track" role="group" aria-label="Your decks">${state.decks.length?[...state.decks].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).map(styledDeckCard).join(''):`<div class="app-empty-decks"><i data-lucide="layers-2"></i><strong>Your study space is ready</strong><p>Create a deck, then add flashcards to start learning.</p><button class="primary-button" data-action="new-deck">Create your first deck</button></div>`}<div class="app-empty-decks" id="appLibraryEmpty" hidden>No decks match these filters. Try a different search.</div></div></div></div><aside class="app-organise-note"><i data-lucide="folder"></i><span><strong>A place for every idea.</strong> Keep related topics together with folders and subdecks.</span></aside></div>`}
function bindContent(){bindContentLegacy();document.querySelectorAll('#appContent [data-library-filter]').forEach(button=>bindOnce(button,'click',()=>{libraryFilter=button.dataset.libraryFilter;document.querySelectorAll('[data-library-filter]').forEach(tab=>tab.classList.toggle('active',tab===button));filterDecks()}));document.querySelectorAll('#appContent [data-layout]').forEach(button=>bindOnce(button,'click',()=>{const list=button.dataset.layout==='list';document.getElementById('libraryGrid')?.classList.toggle('list-view',list);document.querySelectorAll('[data-layout]').forEach(tab=>tab.classList.toggle('active',tab===button))}));document.querySelectorAll('#appContent [data-flip-card]').forEach(button=>bindOnce(button,'click',()=>{const card=button.closest('.app-flashcard-item');const flipped=card.classList.toggle('answer-visible');button.setAttribute('aria-pressed',String(flipped));button.textContent=flipped?'Show question':'Preview answer'}));const subject=document.getElementById('deckSubject');if(subject)bindOnce(subject,'change',filterDecks);const cardSearch=document.getElementById('cardSearch');if(cardSearch)bindOnce(cardSearch,'input',filterCards);const cardDeckFilter=document.getElementById('cardDeckFilter');if(cardDeckFilter)bindOnce(cardDeckFilter,'change',filterCards);const cardSort=document.getElementById('cardSort');if(cardSort)bindOnce(cardSort,'change',filterCards)}
function bindGlobalSearch(){const input=document.getElementById('globalSearch');if(input)bindOnce(input,'input',()=>{if(!user)return;if(view!=='library'){view='library';render()}const local=document.getElementById('deckSearch');if(local){local.value=input.value;filterDecks()}});const sidebarDecks=document.getElementById('sidebarDecks');bindOnce(sidebarDecks,'click',event=>{const button=event.target.closest('[data-open-deck]');if(!button)return;activeDeckId=button.dataset.openDeck;view='deck';render()})}
function filterDecks(){const q=(document.getElementById('deckSearch')?.value||'').trim().toLowerCase(),subject=document.getElementById('deckSubject')?.value||'all',sort=document.getElementById('deckSort')?.value||'added';let decks=state.decks.filter(d=>(d.name+' '+(d.subject||'General')).toLowerCase().includes(q)&&(subject==='all'||(d.subject||'General')===subject));if(libraryFilter==='practice')decks=decks.filter(d=>dueCards(d).length>0);if(libraryFilter==='recent')decks=decks.filter(d=>d.cards.some(c=>c.seen>0));if(sort==='added')decks.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(sort==='name')decks.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='cards')decks.sort((a,b)=>b.cards.length-a.cards.length);if(sort==='due')decks.sort((a,b)=>dueCards(b).length-dueCards(a).length);if(sort==='recent')decks.sort((a,b)=>b.cards.reduce((n,c)=>n+c.seen,0)-a.cards.reduce((n,c)=>n+c.seen,0));const grid=document.getElementById('libraryGrid');if(!grid)return;grid.innerHTML=decks.length?decks.map(styledDeckCard).join(''):`<div class="app-empty-decks"><i data-lucide="search-x"></i><strong>No matching decks</strong><p>Try a different search or filter.</p></div>`;document.getElementById('appDeckCount').textContent=`${decks.length} ${decks.length===1?'deck':'decks'}`;if(window.lucide)lucide.createIcons();bindContent();updateHorizontalSlider(grid.closest('[data-horizontal-slider]'))}
function cardLibrary(){const cards=allCards().sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)),firstDeck=state.decks[0],decks=state.decks;return `<div class="app-card-library"><section class="app-overview-head"><div><div class="eyebrow">YOUR STUDY SPACE</div><h1>Flashcard Library</h1><p>Find a card, refresh your memory, and keep moving forward.</p></div><button class="primary-button" data-action="${firstDeck?'new-card':'new-deck'}" ${firstDeck?`data-id="${firstDeck.id}"`:''}><span class="button-icon"><i data-lucide="plus"></i></span>Create Flashcard</button></section><section class="app-library-stats"><div><i data-lucide="layers-2"></i><strong>${cards.length}</strong><span>Total cards</span></div><div><i data-lucide="library-big"></i><strong>${decks.length}</strong><span>Decks</span></div><div><i data-lucide="circle-check"></i><strong>${cards.filter(card=>card.seen>0).length}</strong><span>Reviewed</span></div></section><div class="app-card-toolbar"><label class="app-library-search"><i data-lucide="search"></i><input id="cardSearch" type="search" placeholder="Search cards or decks" aria-label="Search flashcards"></label><select id="cardDeckFilter" aria-label="Filter by deck"><option value="all">All decks</option>${decks.map(deck=>`<option value="${deck.id}">${esc(deck.name)}</option>`).join('')}</select><select id="cardSort" aria-label="Sort flashcards"><option value="recent">Sort: Recently added</option><option value="question">Sort: Question</option><option value="deck">Sort: Deck</option><option value="reviewed">Sort: Most reviewed</option></select></div><div class="app-library-title"><h2>Your flashcards</h2><span id="cardCount">${cards.length} ${cards.length===1?'card':'cards'}</span></div><div class="recall-horizontal-slider" data-horizontal-slider="flashcards">${sliderControls('flashcards','cardGrid')}<div class="recall-slider-viewport"><div id="cardGrid" class="grid app-flashcard-grid recall-slider-track" role="group" aria-label="Flashcards">${cards.length?cards.map(flashcardTile).join(''):`<div class="app-empty-decks"><i data-lucide="library-big"></i><strong>${decks.length?'No flashcards yet':'Create a deck to begin'}</strong><p>${decks.length?'Add your first question and answer to this library.':'Create a deck, then add flashcards to it.'}</p><button class="primary-button" data-action="${firstDeck?'new-card':'new-deck'}" ${firstDeck?`data-id="${firstDeck.id}"`:''}>${firstDeck?'Add your first card':'Create a deck'}</button></div>`}</div></div></div></div>`}
function flashcardTile(card,index){const deck=state.decks.find(item=>item.id===card.deckId),[bg,fg]=deckColor(Math.max(0,state.decks.indexOf(deck)));return `<article class="app-flashcard-item" style="--card-delay:${Math.min(index,8)*45}ms"><div class="app-flashcard-top"><span class="app-deck-emoji" style="background:${bg};color:${fg}">${deckIcon(deck)}</span><span>${esc(deck?.name||'Deck')}</span><button class="app-card-edit" data-edit-card="${card.id}" data-deck="${card.deckId}" aria-label="Edit flashcard"><i data-lucide="pencil"></i></button></div><div class="app-flashcard-question"><div class="app-flashcard-side">QUESTION</div><h3>${esc(card.q)}</h3></div><div class="app-flashcard-answer"><div class="app-flashcard-divider"></div><div class="app-flashcard-side">ANSWER</div><p>${esc(card.a)}</p></div><div class="app-flashcard-bottom"><button class="app-card-flip" type="button" data-flip-card aria-pressed="false">Preview answer</button><span>${card.seen||0} ${(card.seen||0)===1?'review':'reviews'}</span><button class="app-card-study" data-action="study-deck" data-id="${card.deckId}"><i data-lucide="play"></i>Study deck</button></div></article>`}
function filterCards(){const query=(document.getElementById('cardSearch')?.value||'').trim().toLowerCase(),deckId=document.getElementById('cardDeckFilter')?.value||'all',sort=document.getElementById('cardSort')?.value||'recent';let cards=allCards().filter(card=>(deckId==='all'||card.deckId===deckId)&&(`${card.q} ${card.a} ${card.deckName}`).toLowerCase().includes(query));if(sort==='recent')cards.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(sort==='question')cards.sort((a,b)=>a.q.localeCompare(b.q));if(sort==='deck')cards.sort((a,b)=>a.deckName.localeCompare(b.deckName)||a.q.localeCompare(b.q));if(sort==='reviewed')cards.sort((a,b)=>b.seen-a.seen);const grid=document.getElementById('cardGrid');if(!grid)return;grid.innerHTML=cards.length?cards.map(flashcardTile).join(''):`<div class="app-empty-decks"><i data-lucide="search-x"></i><strong>No matching flashcards</strong><p>Try another search or choose a different deck.</p></div>`;document.getElementById('cardCount').textContent=`${cards.length} ${cards.length===1?'card':'cards'}`;if(window.lucide)lucide.createIcons();bindContent();updateHorizontalSlider(grid.closest('[data-horizontal-slider]'))}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY+':guest'));if(saved&&Array.isArray(saved.decks))return saved}catch{}return structuredClone(starter)}
function save(){render();if(user?.guest){try{localStorage.setItem(STORE_KEY+':guest',JSON.stringify(state))}catch(error){showToast('Could not save on this device. Check your available browser storage.','error')}return}}
function sync(method,path,body,onDone){if(!user||user.guest||!window.RecallBackend?.ready)return;RecallBackend.write(method,path,body).then(r=>{if(onDone&&r)onDone(r)}).catch(error=>{showToast('Could not sync: '+error.message,'error');RecallBackend.enqueue(()=>reloadFromServer()).catch(()=>{})})}
async function reloadFromServer(){const data=await RecallBackend.request('GET','/bootstrap',null,{timeoutMs:30000});state={decks:data.decks,sessions:data.sessions,createdAt:Date.now()};render()}
function recordSession(){const session={day:todayKey(),reviewed:study.reviewed,correct:study.correct};state.sessions.push(session);sync('POST','/sessions',session);save()}
function id(){return crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function todayKey(d=new Date()){return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`}
function allCards(){return state.decks.flatMap(d=>d.cards.map(c=>({...c,deckId:d.id,deckName:d.name,emoji:d.emoji})))}
function dueCards(deck=null){const now=Date.now();return (deck?deck.cards:allCards()).filter(c=>!c.due||c.due<=now)}
function stats(){let cards=allCards(),reviews=cards.reduce((n,c)=>n+c.seen,0),correct=cards.reduce((n,c)=>n+c.right,0);return{cards:cards.length,reviews,accuracy:reviews?Math.round(correct/reviews*100):0,due:dueCards().length}}
function getStreak(){const days=new Set(state.sessions.map(s=>s.day));let date=new Date(),streak=0;if(!days.has(todayKey(date)))date.setDate(date.getDate()-1);while(days.has(todayKey(date))){streak++;date.setDate(date.getDate()-1)}return streak}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function deckIconName(deck){return deckIconOptions.some(([name])=>name===deck?.icon)?deck.icon:(legacyDeckIcons[deck?.emoji]||'layers-2')}
function deckIcon(deck){return `<i data-lucide="${deckIconName(deck)}" aria-hidden="true"></i>`}
function deckColor(i){return colors[i%colors.length]}
function dateLabel(){return new Intl.DateTimeFormat('en',{weekday:'short',month:'short',day:'numeric'}).format(new Date())}
function render(){if(!user){document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.getElementById('appContent').innerHTML=landingView();bindLanding();updateInstallButtons();if(window.lucide)lucide.createIcons();return}document.querySelector('.sidebar').hidden=false;document.querySelector('.topbar').hidden=false;document.getElementById('sessionButton').textContent=user.guest?'Exit guest':'Sign out';document.getElementById('todayLabel').textContent=user.guest?'Guest mode · saved on this device':dateLabel();const meta=user.user_metadata||{},displayName=user.guest?'Guest':(meta.full_name||meta.name||user.email?.split('@')[0]||'Learner'),photo=meta.avatar_url||meta.picture;document.getElementById('profileName').textContent=displayName;document.getElementById('profileCaption').textContent=user.guest?'Saved on this device':(user.email||'Signed in with Google');for(const avatarId of ['profileAvatar','headerAvatar'])document.getElementById(avatarId).innerHTML=photo?`<img src="${esc(photo)}" alt="" referrerpolicy="no-referrer">`:esc(displayName.slice(0,1).toUpperCase());document.getElementById('navDeckCount').textContent=state.decks.length;document.getElementById('sidebarDecks').innerHTML=state.decks.map((d,i)=>`<button class="side-deck" data-open-deck="${d.id}"><span class="deck-emoji">${deckIcon(d)}</span>${esc(d.name)}<span class="side-total">${d.cards.length}</span></button>`).join('');
 document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 const names={dashboard:'Overview',library:'My decks',cards:'Flashcard Library',stats:'Study stats',study:'Study session',deck:'Deck details'};document.getElementById('breadcrumbCurrent').textContent=names[view]||'Overview';
 const root=document.getElementById('appContent');if(view==='dashboard')root.innerHTML=dashboard();else if(view==='library')root.innerHTML=library();else if(view==='cards')root.innerHTML=cardLibrary();else if(view==='stats')root.innerHTML=statistics();else if(view==='study')root.innerHTML=studyView();else if(view==='deck')root.innerHTML=deckDetail();bindContent();bindGlobalSearch();updateInstallButtons();if(window.lucide)lucide.createIcons();initHorizontalSliders()}
function deckDetail(){const d=state.decks.find(x=>x.id===activeDeckId);if(!d){view='library';return library()}const i=state.decks.indexOf(d),[bg,fg]=deckColor(i),due=dueCards(d).length;return `<div class="page-head"><div><div class="eyebrow"><button class="quiet-button" data-view="library"><i data-lucide="arrow-left"></i> My decks</button></div><h1><span class="deck-title-icon">${deckIcon(d)}</span> ${esc(d.name)}</h1><p>${esc(d.subject||'General')} · ${d.cards.length} cards · ${due} ready to review</p></div><div class="deck-actions"><button class="secondary-button" data-action="new-card" data-id="${d.id}"><i data-lucide="plus"></i> Add card</button><button class="secondary-button" data-action="study-shuffle" data-id="${d.id}"><i data-lucide="shuffle"></i> Shuffle questions</button><button class="primary-button" data-action="study-deck" data-id="${d.id}"><i data-lucide="play"></i> Study deck</button></div></div><section class="panel"><div class="panel-heading"><h2>Flashcards</h2><span>Choose a card to edit</span></div>${d.cards.length?`<div class="deck-list">${[...d.cards].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).map((c,n)=>`<div class="deck-row card-edit-row" data-edit-card="${c.id}" data-deck="${d.id}"><div class="deck-visual" style="width:31px;height:31px;background:${bg};color:${fg};font-size:12px">${String(n+1).padStart(2,'0')}</div><div class="deck-info"><strong>${esc(c.q)}</strong><span>${esc(c.a.slice(0,100))}${c.a.length>100?'…':''}</span></div><span class="row-arrow"><i data-lucide="chevron-right"></i></span></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon"><i data-lucide="gallery-vertical-end"></i></div><strong>This deck is ready for its first card</strong><p>Add a question and answer to begin studying.</p><button class="secondary-button" data-action="new-card" data-id="${d.id}"><i data-lucide="plus"></i> Add your first card</button></div>`}</section>`}
function statistics(){
  const s=stats(),days=[];
  for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=todayKey(d);days.push({label:new Intl.DateTimeFormat('en',{weekday:'short'}).format(d),n:state.sessions.filter(x=>x.day===key).reduce((a,x)=>a+x.reviewed,0)})}
  const max=Math.max(1,...days.map(d=>d.n));
  const bars=days.map(d=>`<div class="chart-column"><div class="bar secondary" style="height:${Math.max(3,d.n/max*90)}%"></div><div class="bar" style="height:${Math.max(3,d.n/max*72)}%"></div></div>`).join('');
  const mastered=allCards().filter(c=>c.interval>=7).length,streak=getStreak();
  return `<div class="page-head"><div><div class="eyebrow">YOUR PROGRESS</div><h1>Study stats</h1><p>Every review is a small investment in remembering.</p></div><span class="secondary-button">Last 7 days</span></div><div class="grid stats-row"><article class="stat-card stat-reviews"><div class="stat-top"><span>Total reviews</span><span class="stat-icon"><i data-lucide="book-open"></i></span></div><div class="stat-value">${s.reviews}</div><div class="stat-note">Cards reviewed so far</div></article><article class="stat-card stat-correct"><div class="stat-top"><span>Correct answers</span><span class="stat-icon"><i data-lucide="circle-check"></i></span></div><div class="stat-value">${s.reviews?s.accuracy:0}%</div><div class="stat-note">Overall recall accuracy</div></article><article class="stat-card stat-streak"><div class="stat-top"><span>Active streak</span><span class="stat-icon"><i data-lucide="flame"></i></span></div><div class="stat-value">${streak}<span class="stat-unit">${streak===1?'day':'days'}</span></div><div class="stat-note">Consecutive study days</div></article><article class="stat-card stat-mastered"><div class="stat-top"><span>Cards mastered</span><span class="stat-icon"><i data-lucide="target"></i></span></div><div class="stat-value">${mastered}</div><div class="stat-note">Spaced a week or more</div></article></div><div class="grid stats-layout"><section class="panel chart-panel"><div class="panel-heading"><h2>Review activity</h2><span>CARDS PER DAY</span></div><div class="chart">${bars}</div><div class="chart-labels">${days.map(d=>`<span>${d.label}</span>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>Recall accuracy</h2><span>ALL TIME</span></div><div class="accuracy-ring" style="background:conic-gradient(#4f9b70 0deg ${s.accuracy*3.6}deg,#edf1ed ${s.accuracy*3.6}deg)"><div class="accuracy-hole"><strong>${s.accuracy}%</strong><span>accuracy</span></div></div><div class="stat-list"><div class="stat-line"><span>Cards answered</span><strong>${s.reviews}</strong></div><div class="stat-line"><span>Study sessions</span><strong>${state.sessions.length}</strong></div><div class="stat-line"><span>Due today</span><strong>${s.due}</strong></div></div></section></div><h2 class="section-title">Deck progress</h2><section class="panel"><div class="deck-list">${state.decks.map((d,i)=>{const count=d.cards.length,done=d.cards.filter(c=>c.interval>=7).length,percent=count?Math.round(done/count*100):0;return `<div class="deck-row"><div class="deck-visual" style="background:${deckColor(i)[0]};color:${deckColor(i)[1]}">${deckIcon(d)}</div><div class="deck-info"><strong>${esc(d.name)}</strong><span>${count} cards · ${done} mastered</span></div><div class="deck-progress"><div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div><small>${percent}%</small></div></div>`}).join('')||'<div class="empty-state"><strong>Add a deck to see your progress</strong></div>'}</div></section></div>`
}
function studyView(){if(!study)return dashboard();if(study.done)return `<div class="study-wrap"><div class="panel session-complete"><div class="complete-icon"><i data-lucide="sprout"></i></div><div class="eyebrow">SESSION COMPLETE</div><h2>Nice work. You showed up.</h2><p>Every review helps your brain hold on to what matters.</p><div class="session-stats"><div><strong>${study.reviewed}</strong><span>cards reviewed</span></div><div><strong>${study.reviewed?Math.round(study.correct/study.reviewed*100):0}%</strong><span>accuracy</span></div><div><strong>${study.duration}</strong><span>minutes</span></div></div><button class="primary-button" data-action="finish-study">Back to overview</button></div></div>`;const c=study.cards[study.index],d=state.decks.find(d=>d.id===study.deckId);if(!c){study.done=true;study.duration=Math.max(1,Math.round((Date.now()-study.started)/60000));return studyView()}const n=study.index+1;return `<div class="study-wrap"><div class="study-top"><div class="study-deck-name"><div class="deck-visual study-deck-icon">${deckIcon(d)}</div><div><strong>${esc(d?.name||'All decks')}</strong><span>Study session</span></div></div><div class="study-progress"><span>${n} of ${study.cards.length}</span><div class="progress-track"><div class="progress-fill" style="width:${(n-1)/study.cards.length*100}%"></div></div><button class="quiet-button" data-action="end-study">End</button></div></div><article class="study-card ${study.revealed?'revealed':''}" id="flashcard" tabindex="0" role="button" aria-label="${study.revealed?'Answer revealed':'Reveal answer'}"><span class="card-label">${study.revealed?'ANSWER':'QUESTION'}</span><div class="flash-content">${study.revealed?`<p>${esc(c.a)}</p>`:`<h2>${esc(c.q)}</h2>`}</div><span class="flip-hint">${study.revealed?'How well did you remember?':'Click anywhere or press space to reveal'}</span></article>${study.revealed?`<div class="study-actions"><button class="wrong-button" data-action="rate" data-correct="false"><i data-lucide="rotate-ccw"></i> Study again</button><button class="right-button" data-action="rate" data-correct="true"><i data-lucide="circle-check"></i> Got it</button></div>`:''}</div>`}
function bindOnce(element,event,handler){if(!element||element.dataset.bound)return;element.dataset.bound='1';element.addEventListener(event,handler)}
function bindContentLegacy(){document.querySelectorAll('#appContent [data-view]').forEach(b=>bindOnce(b,'click',()=>{view=b.dataset.view;study=null;render()}));document.querySelectorAll('#appContent [data-open-deck]').forEach(b=>bindOnce(b,'click',e=>{if(e.target.closest('[data-action],.card-menu'))return;activeDeckId=b.dataset.openDeck;view='deck';render()}));document.querySelectorAll('#appContent [data-action]').forEach(b=>bindOnce(b,'click',e=>{e.stopPropagation();action(b.dataset.action,b.dataset)}));document.querySelectorAll('#appContent [data-menu]').forEach(b=>bindOnce(b,'click',e=>{e.stopPropagation();const m=document.getElementById('menu-'+b.dataset.menu);m.hidden=!m.hidden}));document.querySelectorAll('#appContent [data-edit-card]').forEach(b=>bindOnce(b,'click',()=>openCardModal(b.dataset.deck,b.dataset.editCard)));const search=document.getElementById('deckSearch');if(search)bindOnce(search,'input',filterDecks);const sort=document.getElementById('deckSort');if(sort)bindOnce(sort,'change',filterDecks);const flash=document.getElementById('flashcard');if(flash){bindOnce(flash,'click',reveal);bindOnce(flash,'keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();reveal()}})}}
function filterDecksLegacy(){const q=document.getElementById('deckSearch').value.toLowerCase(),sort=document.getElementById('deckSort').value;let decks=state.decks.filter(d=>(d.name+' '+d.subject).toLowerCase().includes(q));if(sort==='cards')decks.sort((a,b)=>b.cards.length-a.cards.length);if(sort==='due')decks.sort((a,b)=>dueCards(b).length-dueCards(a).length);document.getElementById('libraryGrid').innerHTML=decks.length?decks.map(deckCard).join(''):'<div class="panel empty-state"><strong>No matching decks</strong><p>Try another search.</p></div>';bindContent()}
function action(type,data){if(type==='open-deck'){activeDeckId=data.id;view='deck';render()}if(type==='new-deck')openDeckModal();if(type==='edit-deck')openDeckModal(data.id);if(type==='delete-deck')deleteDeck(data.id);if(type==='new-card')openCardModal(data.id);if(type==='study-deck')startStudy(data.id,true,false);if(type==='study-shuffle')startStudy(data.id,true,true);if(type==='start-due')startStudy(null,false,true);if(type==='rate')rate(data.correct==='true');if(type==='finish-study'){study=null;view='dashboard';render()}if(type==='end-study'){if(study.reviewed){recordSession()}study=null;view='dashboard';render()}}
function openModal(html){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal">${html}</div></div>`;document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal)}function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function openDeckModal(deckId=null){const d=state.decks.find(x=>x.id===deckId);openModal(`<div class="modal-head"><h2>${d?'Edit deck':'Create a deck'}</h2><button class="close-modal" data-close-modal>×</button></div><form id="deckForm"><div class="form-field"><label for="deckName">Deck name</label><input id="deckName" name="name" required maxlength="48" placeholder="e.g. Cell Biology" value="${esc(d?.name||'')}"/></div><div class="form-field"><label for="deckSubject">Subject</label><input id="deckSubject" name="subject" maxlength="32" placeholder="e.g. Biology" value="${esc(d?.subject||'')}"/></div><div class="form-field"><label for="deckIcon">Choose an icon</label><select id="deckIcon" name="icon">${deckIconOptions.map(([value,label])=>`<option value="${value}" ${value===(d?.icon||deckIconName(d))?"selected":""}>${label}</option>`).join("")}</select></div><div class="modal-actions"><button type="button" class="quiet-button" data-close-modal>Cancel</button><button class="primary-button">${d?'Save changes':'Create deck'}</button></div></form>`);document.getElementById('deckForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),values={name:fd.get('name').trim(),subject:fd.get('subject').trim()||'General',icon:fd.get('icon')};if(d){Object.assign(d,values);sync('PATCH','/decks/'+d.id,values)}else{const newDeck={...values,id:id(),cards:[],createdAt:Date.now()};state.decks.push(newDeck);sync('POST','/decks',{id:newDeck.id,...values});lastAddedDeckId=newDeck.id;setTimeout(()=>{if(lastAddedDeckId===newDeck.id)lastAddedDeckId=null},500)}closeModal();save();showToast(d?'Deck updated':'Deck created','success')}}
function openCardModal(deckId,cardId=null){const d=state.decks.find(x=>x.id===deckId),c=d?.cards.find(x=>x.id===cardId);if(!d)return;openModal(`<div class="modal-head"><h2>${c?'Edit flashcard':'Add a flashcard'}</h2><button class="close-modal" data-close-modal>×</button></div><form id="cardForm"><div class="form-field"><label for="cardQuestion">Question</label><textarea id="cardQuestion" name="q" required maxlength="500" placeholder="Write a clear question">${esc(c?.q||'')}</textarea></div><div class="form-field"><label for="cardAnswer">Answer</label><textarea id="cardAnswer" name="a" required maxlength="1000" placeholder="Add the answer and a helpful detail">${esc(c?.a||'')}</textarea></div><div class="form-help">Tip: one idea per card makes review more effective.</div><div class="modal-actions">${c?'<button type="button" class="delete-button" id="deleteCard">Delete card</button>':''}<button type="button" class="quiet-button" data-close-modal>Cancel</button><button class="primary-button">${c?'Save changes':'Add card'}</button></div></form>`);document.getElementById('cardForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);if(c){c.q=fd.get('q').trim();c.a=fd.get('a').trim();sync('PATCH','/cards/'+c.id,{q:c.q,a:c.a})}else{const newCard={id:id(),q:fd.get('q').trim(),a:fd.get('a').trim(),interval:0,due:0,seen:0,right:0,createdAt:Date.now()};d.cards.push(newCard);sync('POST','/decks/'+d.id+'/cards',{id:newCard.id,q:newCard.q,a:newCard.a});lastAddedCardId=newCard.id;setTimeout(()=>{if(lastAddedCardId===newCard.id)lastAddedCardId=null},500)}closeModal();save();showToast(c?'Card updated':'Card added','success')};if(c)document.getElementById('deleteCard').onclick=()=>{sync('DELETE','/cards/'+c.id);d.cards=d.cards.filter(x=>x.id!==c.id);closeModal();save();showToast('Card deleted','success')}}
function deleteDeck(deckId){const d=state.decks.find(x=>x.id===deckId);if(!d)return;openModal(`<div class="modal-head"><h2>Delete “${esc(d.name)}”?</h2><button class="close-modal" data-close-modal>×</button></div><p style="font-size:12px;color:#7f8b84;line-height:1.6">This will permanently remove this deck and its ${d.cards.length} flashcards ${user?.guest?'from this browser':'from your account'}.</p><div class="modal-actions"><button class="quiet-button" data-close-modal>Keep deck</button><button class="primary-button" style="background:#bf615a" id="confirmDelete">Delete deck</button></div>`);document.getElementById('confirmDelete').onclick=()=>{sync('DELETE','/decks/'+deckId);state.decks=state.decks.filter(x=>x.id!==deckId);closeModal();view='library';save();showToast('Deck deleted','success')}}
function startStudy(deckId,includeScheduled=false,shuffle=false){const d=state.decks.find(x=>x.id===deckId);if(d&&!d.cards.length){showToast('No cards in deck','info');return}const pool=d&&includeScheduled?d.cards:(d?dueCards(d):dueCards()),cards=pool.slice();if(shuffle)cards.sort(()=>Math.random()-.5);if(!cards.length){showToast('You’re all caught up on this deck ','success');return}study={deckId:deckId||null,cards:cards.map(c=>({id:c.id,deckId:d?.id||c.deckId,q:c.q,a:c.a})),index:0,revealed:false,reviewed:0,correct:0,started:Date.now()};view='study';render()}
function reveal(){if(study&&!study.done&&!study.revealed){study.revealed=true;render()}}
function rate(correct){const current=study.cards[study.index],d=state.decks.find(x=>x.id===current.deckId),c=d?.cards.find(x=>x.id===current.id);if(c){c.seen++;if(correct){c.right++;c.interval=c.interval?Math.min(30,c.interval*2):1;c.due=Date.now()+c.interval*86400000}else{c.interval=0;c.due=Date.now()+10*60000}sync('POST','/cards/'+c.id+'/review',{correct},card=>Object.assign(c,{interval:card.interval,due:card.due,seen:card.seen,right:card.right}))}study.reviewed++;if(correct){study.correct++;study.index++}study.revealed=false;if(study.index>=study.cards.length){study.done=true;study.duration=Math.max(1,Math.round((Date.now()-study.started)/60000));recordSession()}else render()}
function showToast(msg,kind='info'){const t=document.getElementById('toast'),now=Date.now();if(msg===lastToastMessage&&now-lastToastAt<850)return;lastToastMessage=msg;lastToastAt=now;if(t.dataset)t.dataset.kind=kind;const message=t.querySelector?.('[data-toast-message]');if(message)message.textContent=msg;else t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,4200)}
function hideToast(){const toast=document.getElementById('toast');toast.classList.remove('show');clearTimeout(toastTimer)}
document.querySelector('.toast-dismiss')?.addEventListener('click',hideToast);
function landingView(){return `<section class="landing"><header class="landing-nav"><a class="brand" href="#"><span class="brand-mark">r</span><span>recall<span class="brand-dot">.</span></span></a><div class="landing-nav-actions"><button class="quiet-button install-button" data-install hidden>Install app</button><button class="quiet-button" data-signin>Sign in</button></div></header><div class="landing-body"><div class="landing-copy"><div class="eyebrow">A CALMER WAY TO STUDY</div><h1>Make what you learn<br><em>stay with you.</em></h1><p>Turn your notes into a study routine that works. Build your own flashcard decks, review at your pace, and keep track of what you know.</p><div class="landing-actions"><button class="primary-button" data-signin>Sign in</button><button class="secondary-button" id="landingGuest">Continue as guest <span>→</span></button></div><div class="landing-note">No account needed to get started.</div></div><div class="landing-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="float-card float-card-back"><span><i data-lucide="sparkles"></i> QUICK REVIEW</span><b>What’s one thing<br>you learned today?</b></div><div class="float-card float-card-front"><span>YOUR STUDY SPACE</span><b>Small steps.<br>Lasting recall.</b><i data-lucide="sparkles"></i></div><div class="landing-spark spark-a"><i data-lucide="sparkles"></i></div><div class="landing-spark spark-b"><i data-lucide="sparkles"></i></div></div></div><footer class="landing-footer"><span>Recall · Make it stick</span><span>Study a little. Remember a lot.</span></footer></section>`}
function bindLanding(){document.querySelectorAll('[data-signin]').forEach(b=>b.onclick=openSignIn);document.getElementById('landingGuest').onclick=()=>{sessionStorage.setItem(GUEST_SESSION_KEY,'1');user={id:'guest',guest:true};state=loadState();view=requestedView;render()}}
function loginView(){return `<div class="modal-head"><h2>Sign in to Recall</h2><button class="close-modal" data-close-modal aria-label="Close">×</button></div><p class="auth-modal-copy">Continue with your Google account to sync your decks and progress across all your devices.</p><button class="google-button" id="googleSignIn"><svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#4285F4" d="M43.6 24.5c0-1.4-.1-2.8-.4-4.1H24v7.8h11a9.4 9.4 0 0 1-4.1 6.2v5.1h6.6c3.9-3.6 6.1-8.8 6.1-15Z"/><path fill="#34A853" d="M24 44c5.5 0 10.1-1.8 13.5-4.9l-6.6-5.1c-1.8 1.2-4.1 2-6.9 2-5.3 0-9.8-3.6-11.4-8.4H5.8v5.3C9.2 39.5 16.1 44 24 44Z"/><path fill="#FBBC05" d="M12.6 27.6a12 12 0 0 1 0-7.2v-5.3H5.8a20 20 0 0 0 0 17.8l6.8-5.3Z"/><path fill="#EA4335" d="M24 12c3 0 5.7 1 7.8 3.1l5.8-5.8C34.1 6.1 29.5 4 24 4 16.1 4 9.2 8.5 5.8 15.1l6.8 5.3C14.2 15.6 18.7 12 24 12Z"/></svg>Continue with Google</button><div id="authMessage" class="auth-message"></div>`}
function openSignIn(){authMode='signin';openModal(loginView());bindLogin()}
function setButtonLoading(button,loading,label='Please wait…'){
  if(!button)return;
  if(loading){if(!button.dataset.originalHtml)button.dataset.originalHtml=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=`<span class="button-spinner" aria-hidden="true"></span>${label}`;return}
  button.disabled=false;button.removeAttribute('aria-busy');if(button.dataset.originalHtml){button.innerHTML=button.dataset.originalHtml;delete button.dataset.originalHtml}
}
function bindLogin(){
  const message=document.getElementById('authMessage'),googleButton=document.getElementById('googleSignIn');
  googleButton.onclick=async()=>{
    if(!window.RecallBackend?.ready){message.textContent='Sign-in is not configured yet. See docs/DEPLOYMENT.md.';return}
    setButtonLoading(googleButton,true,'Connecting…');message.textContent='';
    try{await RecallBackend.signInWithGoogle()}
    catch(error){message.textContent=RecallBackend.friendlyAuthError(error)}
    finally{if(googleButton.isConnected)setButtonLoading(googleButton,false)}
  };
}
function closeMobileDrawer(restoreFocus=false){const sidebar=document.getElementById('appSidebar'),overlay=document.getElementById('mobileNavOverlay'),toggle=document.getElementById('menuToggle');if(!sidebar||!overlay||!toggle)return;sidebar.classList.remove('mobile-open');overlay.hidden=true;document.body.classList.remove('mobile-nav-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');if(restoreFocus)toggle.focus()}
function toggleMobileDrawer(){const sidebar=document.getElementById('appSidebar'),overlay=document.getElementById('mobileNavOverlay'),toggle=document.getElementById('menuToggle');if(!sidebar||!overlay||!toggle)return;const open=!sidebar.classList.contains('mobile-open');if(open){overlay.hidden=false;sidebar.classList.add('mobile-open');document.body.classList.add('mobile-nav-open');toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Close navigation');sidebar.querySelector('.nav-item')?.focus()}else closeMobileDrawer(true)}
function initMobileNavigation(){const sidebar=document.getElementById('appSidebar'),toggle=document.getElementById('menuToggle'),overlay=document.getElementById('mobileNavOverlay'),drawerClose=document.getElementById('drawerClose');toggle?.addEventListener('click',toggleMobileDrawer);drawerClose?.addEventListener('click',()=>closeMobileDrawer(true));overlay?.addEventListener('click',()=>closeMobileDrawer(true));sidebar?.addEventListener('click',event=>{if(event.target.closest('.nav-item,.side-deck'))closeMobileDrawer(true)});sidebar?.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...sidebar.querySelectorAll('a[href],button:not([disabled])')].filter(item=>item.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&sidebar?.classList.contains('mobile-open')){event.preventDefault();closeMobileDrawer(true)}});window.addEventListener('resize',()=>{if(window.innerWidth>760)closeMobileDrawer(false)})}
function renderAuthLoading(){document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.getElementById('appContent').innerHTML='<section class="auth-wrap"><div class="auth-card loading-card"><span class="loader"></span><strong>Opening your workspace…</strong></div></section>'}
function renderLoadError(message){document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.getElementById('appContent').innerHTML=`<section class="auth-wrap"><div class="auth-card loading-card"><strong>We couldn’t load your decks</strong><p style="margin:8px 0 16px;color:#77869a">${esc(message)}</p><button class="primary-button" id="retryLoad">Try again</button> <button class="quiet-button" id="loadErrorSignOut">Sign out</button></div></section>`;document.getElementById('retryLoad').onclick=async()=>{renderAuthLoading();if(await activateSession(user)){closeModal();render()}};document.getElementById('loadErrorSignOut').onclick=()=>window.exitRecallSession()}
async function activateSession(account){sessionStorage.removeItem(GUEST_SESSION_KEY);user=account;view='dashboard';const slow=setTimeout(()=>{const label=document.querySelector('.loading-card strong');if(label)label.textContent='Waking up the server… the first load can take up to a minute.'},4000);try{const data=await RecallBackend.request('GET','/bootstrap',null,{timeoutMs:70000});state={decks:data.decks,sessions:data.sessions,createdAt:Date.now()};authReady=true;return true}catch(error){renderLoadError(error.message);return false}finally{clearTimeout(slow)}}
function bootAuth(){const backend=window.RecallBackend;if(backend&&backend.init()){renderAuthLoading();backend.onAuthChange(async account=>{if(!account){if(sessionStorage.getItem(GUEST_SESSION_KEY)==='1'){user={id:'guest',guest:true};view=requestedView}else user=null;state=loadState();authReady=true;closeModal();render();return}if(user&&!user.guest&&user.id===account.id&&authReady){user=account;render();return}renderAuthLoading();if(await activateSession(account)){closeModal();render()}})}else{if(sessionStorage.getItem(GUEST_SESSION_KEY)==='1'){user={id:'guest',guest:true};view=requestedView}else user=null;state=loadState();authReady=true;render()}}
document.querySelectorAll('button.nav-item[data-view]').forEach(b=>b.addEventListener('click',event=>{event.preventDefault();if(!user)return;view=b.dataset.view;study=null;render()}));document.getElementById('sideAddDeck').onclick=()=>openDeckModal();document.getElementById('helpButton').onclick=()=>openModal(`<div class="modal-head"><h2>About Recall</h2><button class="close-modal" data-close-modal>×</button></div><div class="help-modal"><p><strong>Recall helps you learn a little every day.</strong> Create decks, add question and answer cards, then study and rate how well you remembered each one.</p><p>Cards you know return later, with their interval growing after each correct answer. Cards you miss come back sooner. Signed in, your decks and stats sync to your account; as a guest they stay in this browser.</p><p>Use the sample decks to explore, or create your own from scratch.</p></div><div class="modal-actions"><button class="primary-button" data-close-modal>Got it</button></div>`);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key===' '||e.key==='Enter')&&view==='study'&&study&&!study.revealed&&document.activeElement===document.body){e.preventDefault();reveal()}});
initMobileNavigation();
bootAuth();
window.exitRecallSession=async()=>{if(user?.guest){sessionStorage.removeItem(GUEST_SESSION_KEY);user=null;state=loadState();render();return}if(window.RecallBackend?.ready){await RecallBackend.flush();await RecallBackend.signOut()}};
function updateInstallButtons(){document.querySelectorAll('[data-install]').forEach(button=>button.hidden=!installPrompt)}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;updateInstallButtons()});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-install]');if(!button||!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.querySelectorAll('[data-install]').forEach(item=>item.hidden=true)});
window.addEventListener('appinstalled',()=>{installPrompt=null;document.querySelectorAll('[data-install]').forEach(button=>button.hidden=true)});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(error=>console.warn('Recall offline setup failed:',error)));
